#!/usr/bin/env python3
"""Audit a products CSV for data-quality issues.

Rules:
  negative-price : price < 0
  blank-name     : name is empty or whitespace-only
  duplicate-sku  : row whose sku has already been seen

Writes audit.json mapping each rule to {"count": int, "sample": [rows...]}.
"""
from __future__ import annotations

import argparse
import csv
import json

RULES = ("negative-price", "blank-name", "duplicate-sku")


def load_rows(path: str) -> list[dict[str, str]]:
    with open(path, newline="", encoding="utf-8") as f:
        return list(csv.DictReader(f))


def audit(rows: list[dict[str, str]]) -> dict[str, list[dict[str, str]]]:
    findings: dict[str, list[dict[str, str]]] = {rule: [] for rule in RULES}
    seen_skus: set[str] = set()
    for row in rows:
        try:
            price = float(row["price"])
        except (KeyError, TypeError, ValueError):
            price = None
        if price is not None and price < 0:
            findings["negative-price"].append(row)
        if not str(row.get("name", "")).strip():
            findings["blank-name"].append(row)
        sku = str(row.get("sku", ""))
        if sku in seen_skus:
            findings["duplicate-sku"].append(row)
        else:
            seen_skus.add(sku)
    return findings


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("csv_path", nargs="?", default="products.csv")
    ap.add_argument("json_path", nargs="?", default="audit.json")
    args = ap.parse_args()

    findings = audit(load_rows(args.csv_path))
    report = {
        rule: {"count": len(rows), "sample": rows} for rule, rows in findings.items()
    }
    with open(args.json_path, "w", encoding="utf-8") as f:
        json.dump(report, f, indent=2)

    for rule in RULES:
        print(f"{rule}: {report[rule]['count']}")


if __name__ == "__main__":
    main()

